-- places/count
-- How many provinces, districts and local units are loaded. The import checks 7 / 77 / 753.
--
-- No parameters.
--
-- Generated by `pnpm db:queries` from lib/db/queries/places.ts. Do not edit by hand.

select (select count(*)::int
from provinces) as provinces, (select count(*)::int
from districts) as districts, (select count(*)::int
from local_units) as local_units;
